1	import { useCallback, useMemo, useState } from 'react';
2	import {
3	  DialogCombobox,
4	  DialogComboboxContent,
5	  DialogComboboxTrigger,
6	  DialogComboboxOptionList,
7	  DialogComboboxOptionListSearch,
8	  DialogComboboxOptionListSelectItem,
9	  useDesignSystemTheme,
10	  Tooltip,
11	} from '@databricks/design-system';
12	import { uniqBy } from 'lodash';
13	
14	import { shouldEnableWorkspaces } from '../../common/utils/FeatureUtils';
15	import { extractWorkspaceFromSearchParams, setLastUsedWorkspace, WORKSPACE_QUERY_PARAM } from '../utils/WorkspaceUtils';
16	import { useLocation, useNavigate, useSearchParams } from '../../common/utils/RoutingUtils';
17	import Routes from '../../experiment-tracking/routes';
18	import { useWorkspaces } from '../hooks/useWorkspaces';
19	
20	export const WorkspaceSelector = () => {
21	  const workspacesEnabled = shouldEnableWorkspaces();
22	  const [searchValue, setSearchValue] = useState('');
23	  const location = useLocation();
24	  const [searchParams] = useSearchParams();
25	  const { theme } = useDesignSystemTheme();
26	  const navigate = useNavigate({ bypassWorkspacePrefix: true });
27	  // Extract workspace from query param
28	  const currentWorkspace = extractWorkspaceFromSearchParams(searchParams);
29	
30	  // Fetch workspaces using custom hook
31	  const { workspaces, isLoading, isError, refetch } = useWorkspaces(workspacesEnabled);
32	
33	  // Smart redirect - preserve navigation context
34	  const getNavigationSection = (pathname: string): string => {
35	    if (pathname.includes('/experiments')) return '/experiments';
36	    if (pathname.includes('/models')) return '/models';
37	    if (pathname.includes('/prompts')) return '/prompts';
38	    return '';
39	  };
40	
41	  const handleWorkspaceChange = useCallback(
42	    (nextWorkspace?: string) => {
43	      if (!nextWorkspace || nextWorkspace === currentWorkspace) {
44	        return;
45	      }
46	
47	      // Persist to localStorage for UI hints
48	      setLastUsedWorkspace(nextWorkspace);
49	
50	      // Hard reload to cleanly switch workspace context (clears all caches)
51	      const currentSection = getNavigationSection(location.pathname);
52	      const targetPath = currentSection || '/';
53	      window.location.hash = `#${targetPath}?${WORKSPACE_QUERY_PARAM}=${encodeURIComponent(nextWorkspace)}`;
54	      window.location.reload();
55	    },
56	    [currentWorkspace, location.pathname],
57	  );
58	
59	  // Refresh workspaces when combobox is opened to catch label selector changes
60	  const handleOpenChange = (isOpen: boolean) => {
61	    if (isOpen) {
62	      refetch();
63	    }
64	  };
65	
66	  const options = useMemo(() => {
67	    const allWorkspaces = [...workspaces];
68	
69	    // Add current workspace if it's not in the list (might be invalid)
70	    if (currentWorkspace && !workspaces.some((w) => w.name === currentWorkspace)) {
71	      allWorkspaces.push({ name: currentWorkspace, description: null });
72	    }
73	
74	    return uniqBy(allWorkspaces, 'name');
75	  }, [workspaces, currentWorkspace]);
76	
77	  // Client-side filtering
78	  const filteredOptions = useMemo(() => {
79	    if (!searchValue) {
80	      return options;
81	    }
82	    const lowerSearch = searchValue.toLowerCase();
83	    return options.filter((workspace) => workspace.name.toLowerCase().includes(lowerSearch));
84	  }, [options, searchValue]);
85	
86	  if (!workspacesEnabled) {
87	    return null;
88	  }
89	
90	  return (
91	    <DialogCombobox
92	      componentId="workspace_selector"
93	      label="Workspace"
94	      value={!currentWorkspace ? [] : [currentWorkspace]}
95	      onOpenChange={handleOpenChange}
96	    >
97	      <DialogComboboxTrigger
98	        withInlineLabel={false}
99	        placeholder="Select workspace"
100	        renderDisplayedValue={() => currentWorkspace}
101	        onClear={() => navigate(Routes.rootRoute)}
102	        width="100%"
103	      />
104	      <DialogComboboxContent style={{ zIndex: theme.options.zIndexBase + 100 }} loading={isLoading}>
105	        {isError && (
106	          <div css={{ padding: theme.spacing.sm, color: theme.colors.textValidationDanger }}>
107	            Failed to load workspaces
108	          </div>
109	        )}
110	
111	        {!isError && (
112	          <DialogComboboxOptionList>
113	            <DialogComboboxOptionListSearch onSearch={(value) => setSearchValue(value)}>
114	              {filteredOptions.length === 0 && searchValue ? (
115	                // Provide a dummy item when no results to prevent crash
116	                <DialogComboboxOptionListSelectItem value="" onChange={() => {}} checked={false} disabled>
117	                  No workspaces found
118	                </DialogComboboxOptionListSelectItem>
119	              ) : (
120	                filteredOptions.map((workspace) => {
121	                  const item = (
122	                    <DialogComboboxOptionListSelectItem
123	                      key={workspace.name}
124	                      value={workspace.name}
125	                      onChange={(value) => handleWorkspaceChange(value)}
126	                      checked={workspace.name === currentWorkspace}
127	                    >
128	                      {workspace.name}
129	                    </DialogComboboxOptionListSelectItem>
130	                  );
131	
132	                  // Wrap with Tooltip if workspace has description
133	                  if (workspace.description) {
134	                    return (
135	                      <Tooltip
136	                        key={workspace.name}
137	                        componentId="workspace_selector.tooltip"
138	                        content={workspace.description}
139	                        side="right"
140	                      >
141	                        {item}
142	                      </Tooltip>
143	                    );
144	                  }
145	
146	                  return item;
147	                })
148	              )}
149	            </DialogComboboxOptionListSearch>
150	          </DialogComboboxOptionList>
151	        )}
152	      </DialogComboboxContent>
153	    </DialogCombobox>
154	  );
155	};
